repo=Path.cwd();proof={}
for code,values in rows.items():
    assert len(values)==len(keys),(code,len(values));p=repo/'client/data/locales'/f'{code}.json';old=json.loads(p.read_text('utf-8'));updated=json.loads(p.read_text('utf-8'))
    for key,value in zip(keys,values):assert key not in updated['strings'];updated['strings'][key]=value
    assert all(updated['strings'][k]==v for k,v in old['strings'].items())
    for field in old:
        if field!='strings':assert old[field]==updated[field]
    p.write_text(json.dumps(updated,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');proof[code]=dict(added=dict(zip(keys,values)),old_values_unchanged=True,sha256=hashlib.sha256(p.read_bytes()).hexdigest())
p=Path(r'G:\PR13Evidence\season-balance-20261102-r1\journey-client-locale-additions-r1.original.json');assert not p.exists();p.write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('Added25 keys in11 languages with all existing values preserved.')
